B.a9U=s(["1 Dose Thunfisch im eigenen Saft (ohne Salz/Oel abgegossen)","1 Ei","4-5 EL Haferflocken oder Reismehl"],t.s)
B.a7E=s(["Backofen auf 175 Grad C vorheizen.","Alles zu einer Masse verruehren.","Duenn auf ein Backblech streichen.","15 Minuten backen, abkuehlen, in kleine Wuerfel schneiden."],t.s)
B.awR=new A.hE(B.jG,"Thunfisch-Wuerfel","Herzhaft und sehr beliebt",B.a9U,B.a7E,"Im Kuehlschrank 3-4 Tage, einfrieren moeglich.","Perfekt als hochwertiges Trainings-Leckerli.")
B.aas=s(["150 g Kuerbispuree (ungesuesst, ohne Gewuerze)","200 g Vollkornmehl oder Haferflocken","1 Ei"],t.s)
B.a5A=s(["Backofen auf 180 Grad C vorheizen.","Zutaten zu einem Teig verkneten, ggf. etwas Mehl ergaenzen.","Ausrollen und Formen ausstechen.","20 Minuten backen, bis sie knusprig sind."],t.s)
B.awP=new A.hE(B.jG,"Kuerbis-Kekse","Gut fuer die Verdauung",B.aas,B.a5A,"Trocken gelagert 1-2 Wochen.",null)
B.acS=s(["1 geraspelte Karotte","1/2 geraspelter Apfel (ohne Kerngehaeuse)","150 g Haferflocken","1 Ei"],t.s)
B.aa9=s(["Backofen auf 180 Grad C vorheizen.","Alles vermengen, kleine Taler formen.","18-20 Minuten backen, auskuehlen lassen."],t.s)
B.awT=new A.hE(B.jG,"Karotten-Apfel-Taler","Vitaminreich",B.acS,B.aa9,"In einer Dose ca. 1 Woche.",null)
B.aaH=s(["3 EL Magerquark","frische Petersilie, fein gehackt","Haferflocken zum Binden"],t.s)
B.a5F=s(["Quark mit Petersilie verruehren.","So viele Haferflocken einkneten, bis eine formbare Masse entsteht.","Kleine Baellchen rollen."],t.s)
B.awO=new A.hE(B.tj,"Quark-Kraeuter-Baellchen","In 5 Minuten fertig",B.aaH,B.a5F,"Im Kuehlschrank 2-3 Tage.","Petersilie hilft sogar gegen Mundgeruch.")
B.a75=s(["2 EL Erdnussbutter (OHNE Xylit/Suessstoff, ungesalzen)","Haferflocken"],t.s)
B.a9t=s(["Erdnussbutter mit so vielen Haferflocken verkneten, bis es formbar ist.","Kleine Kugeln rollen und kurz kalt stellen."],t.s)
B.awM=new A.hE(B.tj,"Erdnussbutter-Happen","Nur 2 Zutaten",B.a75,B.a9t,"Im Kuehlschrank ca. 4 Tage.","WICHTIG: Erdnussbutter MUSS xylitfrei sein - Xylit ist giftig.")
B.a6d=s(["Naturjoghurt (ohne Zucker)","einige Heidelbeeren oder Himbeeren"],t.s)
B.adS=s(["Joghurt mit den Beeren verruehren.","In eine Eiswuerfelform oder Silikonform fuellen.","Ueber Nacht einfrieren."],t.s)
B.awI=new A.hE(B.no,"Joghurt-Beeren-Eis","Erfrischung fuer heisse Tage",B.a6d,B.adS,"Im Gefrierfach mehrere Wochen.","Nur kleine Portionen geben - kalt und langsam schlecken lassen.")
B.a9o=s(["ungesalzene Gemuese- oder Huehnerbruehe (selbst gekocht, ohne Zwiebel)"],t.s)
B.aeY=s(["Bruehe abkuehlen lassen.","In Eiswuerfelformen fuellen und einfrieren."],t.s)
B.awL=new A.hE(B.no,"Brueh-Eis","Herzhaft und fluessigkeitsspendend",B.a9o,B.aeY,"Im Gefrierfach mehrere Wochen.","Niemals Fertigbruehe mit Salz/Zwiebel verwenden.")
B.aeZ=s(["etwas Magerquark oder Naturjoghurt","ein paar Haferflocken + Banane"],t.s)
B.aew=s(["Kong-Spielzeug mit der Masse fuellen.","Ueber Nacht einfrieren.","An heissen Tagen oder bei Langeweile geben."],t.s)
B.awJ=new A.hE(B.no,"Gefuellter Kong (gefroren)","Lange Beschaeftigung",B.aeZ,B.aew,"Einzeln eingefroren mehrere Wochen.","Haelt aufgeregte Hunde lange und ruhig beschaeftigt.")
B.aez=s(["250 g Rinderleber","1 Ei","3-4 EL Haferflocken"],t.s)
B.a7k=s(["Leber puerieren, mit Ei und Haferflocken vermengen.","Duenn auf ein Backblech streichen.","Bei 170 Grad C ca. 20 Minuten backen.","Auskuehlen, in winzige Wuerfel schneiden."],t.s)
B.awQ=new A.hE(B.nn,"Leber-Wuerfel","Das Highlight im Training",B.aez,B.a7k,"Im Kuehlschrank 3 Tage, sonst portionsweise einfrieren.","Sehr intensiv - nur kleine Mengen, sonst Durchfall.")
